import React, { useState } from 'react';
import './Register.css';

function Register() {
  const [prenom, setPrenom] = useState('');
  const [telephone, setTelephone] = useState('');
  const [motDePasse, setMotDePasse] = useState('');
  const [role, setRole] = useState('acheteur');

  const handleInscription = () => {
    alert('Inscription réussie pour : ' + prenom + ' en tant que ' + role);
  };

  return (
    <div className="register-page">
      <div className="register-box">
        <h1 className="register-logo">🎵 Varim Music</h1>
        <h2 className="register-titre">Créer un compte</h2>
        <p className="register-sous-titre">Rejoignez la communauté musicale africaine</p>

        <div className="register-champ">
          <label>Prénom</label>
          <input
            type="text"
            placeholder="Votre prénom"
            value={prenom}
            onChange={(e) => setPrenom(e.target.value)}
          />
        </div>

        <div className="register-champ">
          <label>Numéro de téléphone</label>
          <input
            type="tel"
            placeholder="Ex: 06 123 45 67"
            value={telephone}
            onChange={(e) => setTelephone(e.target.value)}
          />
        </div>

        <div className="register-champ">
          <label>Mot de passe</label>
          <input
            type="password"
            placeholder="Choisissez un mot de passe"
            value={motDePasse}
            onChange={(e) => setMotDePasse(e.target.value)}
          />
        </div>

        <div className="register-champ">
          <label>Je suis un</label>
          <div className="register-roles">
            <div
              className={`role-carte ${role === 'acheteur' ? 'active' : ''}`}
              onClick={() => setRole('acheteur')}
            >
              🎧 Acheteur
            </div>
            <div
              className={`role-carte ${role === 'artiste' ? 'active' : ''}`}
              onClick={() => setRole('artiste')}
            >
              🎤 Artiste
            </div>
          </div>
        </div>

        <button className="register-btn" onClick={handleInscription}>
          Créer mon compte
        </button>

        <p className="register-lien">
          Déjà un compte ? <a href="#">Se connecter</a>
        </p>
      </div>
    </div>
  );
}

export default Register;
